+    expect(refs[0]).toEqual({
+      raw: "https://mysite.com/images/logo.png",
+      type: "url",
+      resolved: "https://mysite.com/images/logo.png",
+    });
+  });
+
+  it("detects HTTPS URLs with query parameters", () => {
