+    const refs = detectImageReferences(prompt);
+
+    expect(refs).toHaveLength(1);
+    expect(refs[0]?.type).toBe("url");
+    expect(refs[0]?.raw).toContain("https://cdn.mysite.com/img.jpg");
+  });
+
+  it("detects multiple image references in a prompt", () => {
+    const prompt = `
