+      const doc = new Document();
+      const body = doc.createElement('body');
+      doc.appendChild(body);
+
+      let disconnected = false;
+
+      class OldEl extends Element {
+        constructor() {
+          super('old-el');
+        }
+        disconnectedCallback(): void {
+          disconnected = true;
+        }
+      }
