+        }
+        verify_by_key_type(key.key_type, &key.pubkey, &self.signature, &self.signable_bytes())
+    }
+
+    /// Stateless verify — returns false (needs state for key lookup).
+    pub fn verify_signature(&self) -> bool { false }
