+                if deleg.unlock_at_round.is_some() {
+                    return Err(CoinError::ValidationError("already undelegating".into()));
+                }
+                deleg.unlock_at_round = Some(current_round.saturating_add(crate::tx::UNSTAKE_COOLDOWN_ROUNDS));
+            }
